--
-- Table structure for table `posts`
--

DROP TABLE IF EXISTS `posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `posts` (
  `PostId` int NOT NULL AUTO_INCREMENT,
  `Title` varchar(255) DEFAULT NULL,
  `Content` text,
  `ImageUrl` varchar(255) DEFAULT NULL,
  `CategoryId` int DEFAULT NULL,
  `CreatedAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `IsDeleted` tinyint DEFAULT '0',
  `AuthorId` int DEFAULT NULL,
  `Title_En` varchar(255) DEFAULT NULL,
  `Title_Hi` varchar(255) DEFAULT NULL,
  `Title_Te` varchar(255) DEFAULT NULL,
  `Content_En` text,
  `Content_Hi` text,
  `Content_Te` text,
  PRIMARY KEY (`PostId`),
  KEY `idx_author_id` (`AuthorId`),
  KEY `idx_created_at` (`CreatedAt`),
  KEY `idx_category_created_at` (`CategoryId`,`CreatedAt`),
  KEY `idx_isdeleted` (`IsDeleted`),
  KEY `idx_title_en` (`Title_En`),
  KEY `idx_title_hi` (`Title_Hi`),
  KEY `idx_title_te` (`Title_Te`),
  KEY `idx_isdeleted_cat_author` (`IsDeleted`,`CategoryId`,`AuthorId`),
  FULLTEXT KEY `idx_posts_fulltext_search` (`Title_En`,`Content_En`,`Title`,`Content`),
  CONSTRAINT `posts_ibfk_1` FOREIGN KEY (`CategoryId`) REFERENCES `categories` (`CategoryId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `posts_ibfk_2` FOREIGN KEY (`AuthorId`) REFERENCES `users` (`id`),
  CONSTRAINT `posts_ibfk_3` FOREIGN KEY (`AuthorId`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=205952 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

